"use client"

import * as React from "react"
import { ArrowRight } from "lucide-react"

import { cn } from "@/lib/utils"
import { type NumberFormat } from "@/registry/dashboardcn/lib/format"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardFooter, CardHeader } from "@/components/ui/card"
import { MetricValue } from "@/registry/dashboardcn/ui/metric-value"
import { TickBar } from "@/registry/dashboardcn/ui/tick-bar"

export interface PaymentSummaryRow {
  label: string
  value: React.ReactNode
}

export interface PaymentSummaryCardProps extends React.ComponentProps<typeof Card> {
  metricLabel: string
  value: number
  format?: NumberFormat
  currency?: string
  progress: number
  progressLabel?: string
  segments?: number
  legend?: { label: string; color?: string }[]
  title: string
  rows: PaymentSummaryRow[]
  status?: string
  action?: { label: string; href?: string; onClick?: () => void }
}

/** A segmented headline metric paired with a compact payment or record summary. */
function PaymentSummaryCard({
  metricLabel,
  value,
  format,
  currency,
  progress,
  progressLabel,
  segments = 64,
  legend = [],
  title,
  rows,
  status,
  action,
  className,
  ...props
}: PaymentSummaryCardProps) {
  return (
    <Card
      data-slot="payment-summary-card"
      className={cn("gap-0 overflow-hidden py-0", className)}
      {...props}
    >
      <CardHeader className="gap-3 border-b py-5 [.border-b]:pb-5">
        <div className="border-l-2 pl-3">
          <span className="text-muted-foreground block text-sm">{metricLabel}</span>
          <MetricValue
            value={value}
            format={format}
            currency={currency}
            className="text-3xl font-semibold tracking-tight"
          />
        </div>
        <div className="relative pt-1">
          {progressLabel ? (
            <span
              className="absolute -top-4 text-xs font-medium tabular-nums"
              style={{ left: `min(calc(${Math.min(100, Math.max(0, progress))}% - 1rem), calc(100% - 2rem))` }}
            >
              {progressLabel}
            </span>
          ) : null}
          <TickBar
            value={progress}
            segments={segments}
            animate
            animationDuration={800}
            className="h-9 gap-[3px]"
          />
        </div>
        {legend.length ? (
          <div className="flex gap-5">
            {legend.map((item) => (
              <span key={item.label} className="text-muted-foreground flex items-center gap-2 text-xs">
                <span className="size-2 rounded-full" style={{ backgroundColor: item.color ?? "var(--foreground)" }} />
                <span className="border-b border-dotted">{item.label}</span>
              </span>
            ))}
          </div>
        ) : null}
      </CardHeader>
      <CardContent className="grid gap-4 py-5">
        <h3 className="text-muted-foreground text-sm font-medium">{title}</h3>
        <dl className="grid gap-3 text-sm">
          {rows.map((row) => (
            <div key={row.label} className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-4">
              <dt className="text-muted-foreground">{row.label}</dt>
              <dd className="font-medium tabular-nums">{row.value}</dd>
            </div>
          ))}
          {status ? (
            <div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-4">
              <dt className="text-muted-foreground">Status</dt>
              <dd><Badge variant="secondary" className="rounded-full">{status}</Badge></dd>
            </div>
          ) : null}
        </dl>
      </CardContent>
      {action ? (
        <CardFooter className="pb-5">
          <Button variant="secondary" className="w-full" asChild={Boolean(action.href)} onClick={action.onClick}>
            {action.href ? <a href={action.href}>{action.label}<ArrowRight /></a> : <>{action.label}<ArrowRight /></>}
          </Button>
        </CardFooter>
      ) : null}
    </Card>
  )
}

export { PaymentSummaryCard }

import * as React from "react"

import { cn } from "@/lib/utils"

export interface TickBarProps extends React.ComponentProps<"div"> {
  /** Current value, from 0 to max. */
  value: number
  max?: number
  /** Number of ticks. */
  segments?: number
  /** Any CSS color for the filled ticks. Defaults to chart-1. */
  color?: string
  /** Any CSS color for the unfilled ticks. Defaults to muted. */
  trackColor?: string
  /** "tick" draws thin bars; "pill" draws wide rounded ones. */
  shape?: "tick" | "pill"
  /** Reveal filled ticks in sequence when the bar mounts. */
  animate?: boolean
  /** Total reveal time in milliseconds. */
  animationDuration?: number
}

/** A progress bar drawn as a row of ticks, lit up to the current value. */
function TickBar({
  value,
  max = 100,
  segments = 40,
  color = "var(--chart-1)",
  trackColor,
  shape = "tick",
  animate = false,
  animationDuration = 700,
  className,
  ...props
}: TickBarProps) {
  const fraction = Math.min(1, Math.max(0, value / (max || 1)))
  // Any non-zero value lights at least one tick so small values still register.
  const filled = fraction === 0 ? 0 : Math.max(1, Math.round(fraction * segments))

  return (
    <div
      data-slot="tick-bar"
      data-shape={shape}
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={value}
      className={cn(
        "flex w-full",
        shape === "tick" ? "h-6 gap-[3px]" : "h-4 gap-1.5",
        className
      )}
      {...props}
    >
      {Array.from({ length: segments }, (_, index) => {
        const lit = index < filled
        return (
          <span
            key={index}
            data-filled={lit}
            className={cn(
              "bg-muted relative h-full min-w-0 flex-1 overflow-hidden transition-colors",
              shape === "tick" ? "rounded-[1.5px]" : "rounded-full"
            )}
            style={{ backgroundColor: trackColor }}
          >
            {lit ? (
              <span
                className={cn(
                  "absolute inset-0",
                  shape === "tick" ? "rounded-[1.5px]" : "rounded-full",
                  animate && "motion-safe:animate-in motion-safe:fade-in"
                )}
                style={{
                  backgroundColor: color,
                  ...(animate
                    ? {
                        animationDelay: `${(index / Math.max(1, filled)) * animationDuration * 0.8}ms`,
                        animationDuration: `${Math.max(120, animationDuration * 0.25)}ms`,
                        animationFillMode: "both",
                      }
                    : null),
                }}
              />
            ) : null}
          </span>
        )
      })}
    </div>
  )
}

export { TickBar }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { formatNumber, type NumberFormat } from "@/registry/dashboardcn/lib/format"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

/** Values at or above this are abbreviated by default. */
export const DEFAULT_COMPACT_FROM = 100_000

export interface MetricValueProps extends Omit<React.ComponentProps<"span">, "children"> {
  /** Strings render as-is. */
  value: number | string
  format?: NumberFormat
  currency?: string
  maximumFractionDigits?: number
  /** Values at or above this are abbreviated (e.g. $158K) with the full value in a tooltip. Set to Infinity to always show the full value. */
  compactFrom?: number
  /** Text after the number, e.g. a unit. */
  suffix?: React.ReactNode
}

/** A formatted number. Large values are abbreviated and reveal the full value on hover. */
function MetricValue({
  value,
  format,
  currency,
  maximumFractionDigits,
  compactFrom = DEFAULT_COMPACT_FROM,
  suffix,
  className,
  ...props
}: MetricValueProps) {
  const classes = cn("tabular-nums", className)

  if (typeof value !== "number") {
    return (
      <span data-slot="metric-value" className={classes} {...props}>
        {value}
        {suffix}
      </span>
    )
  }

  const full = formatNumber(value, { format, currency, maximumFractionDigits })
  const abbreviate = format !== "percent" && Math.abs(value) >= compactFrom
  if (!abbreviate) {
    return (
      <span data-slot="metric-value" className={classes} {...props}>
        {full}
        {suffix}
      </span>
    )
  }

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <span
            data-slot="metric-value"
            data-compact=""
            className={cn(classes, "cursor-default")}
            {...props}
          >
            {formatNumber(value, { format, currency, compact: true })}
            {suffix}
          </span>
        </TooltipTrigger>
        <TooltipContent className="tabular-nums">
          {full}
          {suffix}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  )
}

export { MetricValue }

export type NumberFormat = "number" | "compact" | "currency" | "percent"

export interface FormatNumberOptions {
  format?: NumberFormat
  /** ISO 4217 code, used when format is "currency". Defaults to USD. */
  currency?: string
  locale?: string
  maximumFractionDigits?: number
  /** Abbreviate large values, e.g. "$158K" instead of "$158,143". */
  compact?: boolean
}

const formatterCache = new Map<string, Intl.NumberFormat>()

function getFormatter(locale: string, options: Intl.NumberFormatOptions) {
  const key = locale + JSON.stringify(options)
  let formatter = formatterCache.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options)
    formatterCache.set(key, formatter)
  }
  return formatter
}

/**
 * Format a metric value for display.
 *
 * formatNumber(1234567)                          -> "1,234,567"
 * formatNumber(1234567, { format: "compact" })   -> "1.2M"
 * formatNumber(48.2, { format: "currency" })     -> "$48.20"
 * formatNumber(158143, { format: "currency", compact: true }) -> "$158K"
 * formatNumber(0.124, { format: "percent" })     -> "12.4%"
 */
export function formatNumber(
  value: number,
  {
    format = "number",
    currency = "USD",
    locale = "en-US",
    maximumFractionDigits,
    compact = false,
  }: FormatNumberOptions = {}
): string {
  if (!Number.isFinite(value)) return "—"

  // Compact values keep three significant digits: $158K, $1.23M, 41.2K.
  const compactOptions: Intl.NumberFormatOptions = compact
    ? maximumFractionDigits === undefined
      ? { notation: "compact", maximumSignificantDigits: 3 }
      : { notation: "compact", maximumFractionDigits }
    : {}
  switch (format) {
    case "compact":
      return getFormatter(locale, {
        notation: "compact",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    case "currency":
      return getFormatter(locale, {
        style: "currency",
        currency,
        maximumFractionDigits: maximumFractionDigits ?? 2,
        ...compactOptions,
      }).format(value)
    case "percent":
      return getFormatter(locale, {
        style: "percent",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    default:
      return getFormatter(locale, {
        maximumFractionDigits: maximumFractionDigits ?? 0,
        ...compactOptions,
      }).format(value)
  }
}

/**
 * Format a fractional change as a signed percentage.
 *
 * formatDelta(0.124)  -> "+12.4%"
 * formatDelta(-0.03)  -> "-3.0%"
 * formatDelta(0)      -> "0.0%"
 */
export function formatDelta(delta: number, locale = "en-US"): string {
  if (!Number.isFinite(delta)) return "—"
  return getFormatter(locale, {
    style: "percent",
    signDisplay: "exceptZero",
    maximumFractionDigits: 1,
    minimumFractionDigits: 1,
  }).format(delta)
}

/**
 * Fractional change between two values. Returns 0 when there is no baseline.
 */
export function computeDelta(current: number, previous: number): number {
  if (!previous) return 0
  return (current - previous) / Math.abs(previous)
}
